      {tournament.phase === 'complete' && match && <h3>Champion: {tournament.names[match.winner!]}</h3>}
      <div className="tournament-actions">
        {tournament.phase === 'ready' && <button className="control" type="button" onClick={begin}>Start turn</button>}
        {tournament.phase === 'turnEnd' && <button className="control" type="button" onClick={advance}>Next turn</button>}
        {tournament.phase === 'matchEnd' && <button className="control" type="button" onClick={advance}>Next match</button>}
        {tournament.phase === 'complete' ? <button className="control" type="button" onClick={back}>Back to game</button> : <button className="control" type="button" onClick={() => askLeave(back)}>Leave tournament</button>}
      </div>
      {tournament.phase === 'playing' && <>
        <GameStatus game={controller.session.game} best={undefined} celebration={controller.session.celebration} />
        {controller.session.paused && <button className="control" onClick={controller.resume}>Resume</button>}
        <p id="board-help" className="help">Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.</p>
        <Board key={controller.session.generation} game={controller.session.game} activate={controller.activate} />
      </>}
      <div className="bracket"><table><caption>Bracket</caption><thead><tr><th scope="col">Round</th><th scope="col">Player 1</th><th scope="col">Moves</th><th scope="col">Time</th><th scope="col">Player 2</th><th scope="col">Moves</th><th scope="col">Time</th><th scope="col">Winner</th></tr></thead><tbody>
        {Array.from({ length: tournament.names.length - 1 }, (_, index) => {
          const entry = tournament.matches[index];
          const pair = entry?.players ?? playersFor(tournament, index) ?? opening(tournament.names.length)[index];
          return <tr key={index}><td>{roundFor(tournament.names.length, index).name}</td><td>{pair ? tournament.names[pair[0]] : 'TBD'}</td><td>{entry?.results[0]?.moves ?? '—'}</td><td>{entry?.results[0] ? formatElapsed(entry.results[0].elapsedMs) : '—'}</td><td>{pair ? tournament.names[pair[1]] : 'TBD'}</td><td>{entry?.results[1]?.moves ?? '—'}</td><td>{entry?.results[1] ? formatElapsed(entry.results[1].elapsedMs) : '—'}</td><td>{entry?.winner != null ? tournament.names[entry.winner] : '—'}</td></tr>;
        })}
      </tbody></table></div>
    </>}
    <section className="tournament-exchange"><h3>Share tournament</h3><label htmlFor="tournament-json">Tournament JSON</label><textarea className="control" id="tournament-json" rows={8} value={json} onChange={(e) => setJson(e.target.value)} /><div className="tournament-actions"><button className="control" type="button" onClick={() => { setJson(encode(tournament, tournament?.phase === 'playing' ? controller.exportSnapshot() : null)); setNotice('Tournament exported.'); }}>Export tournament</button><button className="control" type="button" onClick={load}>Load tournament</button></div></section>
