  const recorded = useRef(false);
  useEffect(() => { heading.current?.focus(); }, []);
  const match = tournament?.matches.at(-1);
  const player = match?.results[0] ? 1 : 0;
  useEffect(() => {
    if (!tournament || tournament.phase !== 'playing' || !isWon(controller.session.game) || recorded.current) return;
    recorded.current = true;
    const updated = recordResult(tournament, { moves: controller.session.game.moves, elapsedMs: controller.session.game.elapsedMs });
    setTournament(updated);
    if (updated.phase === 'complete') {
      setHistory((old) => {
        const items = [updated, ...old.items].slice(0, 10);
        try { localStorage.setItem(KEY, JSON.stringify({ v: 3, items })); return { items, unavailable: false }; }
        catch { return { items, unavailable: true }; }
