        <td>{pair ? tournament.names[pair[1]] : 'TBD'}</td><td>{entry?.results[1]?.moves ?? '—'}</td><td>{entry?.results[1] ? formatElapsed(entry.results[1].elapsedMs) : '—'}</td>
        <td>{entry?.winner != null ? tournament.names[entry.winner] : '—'}</td>
      </tr>;
    })}
  </tbody></table></div>;
}
